INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('5fa90071-002e-41c5-a9dc-d90cf19a8c3d', 'Laptop Gaming Asus TUF Gaming A15 FA507NU', 'Laptop Gaming Asus TUF Gaming A15 FA507NU sở hữu cấu hình mạnh mẽ với CPU AMD Ryzen 7 7735HS và card đồ họa NVIDIA GeForce RTX 4050, mang đến hiệu năng ấn tượng cho các tựa game AAA và các tác vụ đồ họa chuyên nghiệp.', 'Laptop Gaming', '64cee73d-944f-4270-b8af-f99ce89044ee', 'Asus', '{"CPU": "AMD Ryzen 7 7735HS", "RAM": "16GB DDR5 4800MHz", "Storage": "512GB SSD NVMe PCIe Gen 4", "Display": "15.6 inch FHD IPS 144Hz", "GPU": "NVIDIA GeForce RTX 4050 6GB GDDR6", "OS": "Windows 11 Home", "Weight": "2.2 kg", "Battery": "90WHrs"}', '/static/images/laptop-001.jpg', '["/static/images/laptop-001.jpg"]', 23990000, 28788000, 23990000, 100, 5.0, true, true);
