INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('7cbd64d3-96d6-4bce-96bc-991d46af3560', 'Laptop Gaming Acer Nitro 5 Eagle AN515-57', 'Laptop Gaming Acer Nitro 5 Eagle AN515-57 là lựa chọn tuyệt vời cho người mới bắt đầu với mức giá hợp lý, trang bị CPU Intel Core i5-11400H và card đồ họa NVIDIA GeForce RTX 3050, đủ sức chơi tốt các tựa game phổ biến hiện nay.', 'Laptop Gaming', '64cee73d-944f-4270-b8af-f99ce89044ee', 'Acer', '{"CPU": "Intel Core i5-11400H", "RAM": "8GB DDR4 3200MHz", "Storage": "512GB SSD NVMe PCIe Gen 3", "Display": "15.6 inch FHD IPS 144Hz", "GPU": "NVIDIA GeForce RTX 3050 4GB GDDR6", "OS": "Windows 11 Home", "Weight": "2.3 kg", "Battery": "57WHrs"}', '/static/images/laptop-003.jpg', '["/static/images/laptop-003.jpg"]', 19990000, 23988000, 19990000, 100, 5.0, true, true);
INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('e7543bbe-9912-4791-938b-dc39e8696618', 'Macbook Air M2 2022', 'Macbook Air M2 2022 với thiết kế mỏng nhẹ, sang trọng cùng hiệu năng vượt trội từ chip M2 mới nhất của Apple, là lựa chọn hoàn hảo cho công việc văn phòng, thiết kế đồ họa và các tác vụ hàng ngày.', 'Laptop', 'f8e78ac7-67b5-4f7d-8563-d9ef0fee8fd4', 'Apple', '{"CPU": "Apple M2 8-core", "RAM": "8GB Unified Memory", "Storage": "256GB SSD", "Display": "13.6 inch Liquid Retina", "GPU": "Apple M2 8-core GPU", "OS": "macOS Ventura", "Weight": "1.24 kg", "Battery": "52.6WHrs"}', '/static/images/laptop-004.jpg', '["/static/images/laptop-004.jpg"]', 27990000, 33588000, 27990000, 100, 5.0, true, true);
