INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('322907ad-8403-4700-a77b-3b2dfa368f24', 'PC Gaming GVN VIPER i4070', 'PC Gaming GVN VIPER i4070 là cỗ máy gaming cao cấp với CPU Intel Core i7-13700KF và card đồ họa NVIDIA GeForce RTX 4070, đáp ứng mọi nhu cầu chơi game ở độ phân giải 2K, 4K và các tác vụ đồ họa, render video chuyên nghiệp.', 'PC Gaming', '8686748b-4c7a-4fd5-b988-1e8fa816c001', 'GVN', '{"CPU": "Intel Core i7-13700KF", "RAM": "32GB DDR5 5600MHz", "Storage": "1TB SSD NVMe PCIe Gen 4", "GPU": "NVIDIA GeForce RTX 4070 12GB GDDR6X", "PSU": "Corsair RM850x 850W 80 Plus Gold", "Case": "Corsair 4000D Airflow", "Cooling": "NZXT Kraken X63 RGB", "Mainboard": "MSI MAG Z690 TOMAHAWK WIFI DDR5"}', '/static/images/pc-002.jpg', '["/static/images/pc-002.jpg"]', 42990000, 51588000, 42990000, 100, 5.0, true, true);
INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('cacf612e-a14d-4306-8d91-23c0e47b7572', 'Màn hình Gaming Asus TUF VG27AQ', 'Màn hình Gaming Asus TUF VG27AQ với kích thước 27 inch, độ phân giải QHD, tần số quét 165Hz và công nghệ ELMB-SYNC, mang đến trải nghiệm chơi game mượt mà và hình ảnh sắc nét.', 'Màn hình', 'e9070a5e-c143-4f8a-88e7-f447cecd633f', 'Asus', '{"Size": "27 inch", "Resolution": "2560 x 1440 (QHD)", "Panel": "IPS", "Refresh Rate": "165Hz", "Response Time": "1ms MPRT", "Connectivity": "HDMI 2.0, DisplayPort 1.2", "HDR": "HDR10", "Adaptive Sync": "G-Sync Compatible, FreeSync Premium"}', '/static/images/monitor-001.jpg', '["/static/images/monitor-001.jpg"]', 8990000, 10788000, 8990000, 100, 5.0, true, true);
INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('5fc8558a-3a6e-4b12-b616-cf9389750ccf', 'Màn hình Gaming LG UltraGear 27GP850-B', 'Màn hình Gaming LG UltraGear 27GP850-B với công nghệ Nano IPS, độ phân giải QHD, tần số quét lên đến 180Hz và thời gian phản hồi siêu nhanh 1ms, là lựa chọn lý tưởng cho các game thủ chuyên nghiệp và những người làm việc với đồ họa.', 'Màn hình', 'e9070a5e-c143-4f8a-88e7-f447cecd633f', 'LG', '{"Size": "27 inch", "Resolution": "2560 x 1440 (QHD)", "Panel": "Nano IPS", "Refresh Rate": "180Hz (OC)", "Response Time": "1ms GtG", "Connectivity": "HDMI 2.0, DisplayPort 1.4", "HDR": "HDR10", "Adaptive Sync": "G-Sync Compatible, FreeSync Premium Pro"}', '/static/images/monitor-002.jpg', '["/static/images/monitor-002.jpg"]', 9490000, 11388000, 9490000, 100, 5.0, true, true);
INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('75ffd5e6-7a53-4a00-85f1-6c7fd1d9b4d5', 'Bàn phím cơ Logitech G PRO X', 'Bàn phím cơ Logitech G PRO X với thiết kế tenkeyless nhỏ gọn, switch GX Blue Clicky có thể thay thế và đèn LED RGB 16.8 triệu màu, là lựa chọn lý tưởng cho các game thủ chuyên nghiệp.', 'Bàn phím', '6da6eea4-47d4-4ee7-a12b-2aef25aa0336', 'Logitech', '{"Switch": "GX Blue Clicky", "K\u1ebft n\u1ed1i": "C\u00f3 d\u00e2y USB", "\u0110\u00e8n LED": "RGB 16.8 tri\u1ec7u m\u00e0u", "Ph\u00edm multimedia": "C\u00f3", "K\u00edch th\u01b0\u1edbc": "Tenkeyless (TKL)", "Keycap": "ABS Double-shot", "Polling Rate": "1000Hz"}', '/static/images/keyboard-001.jpg', '["/static/images/keyboard-001.jpg"]', 3290000, 3948000, 3290000, 100, 5.0, true, true);
INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('0f7c553b-e963-4921-9beb-970363f286cf', 'Bàn phím cơ Akko 3087 v2 DS Midnight', 'Bàn phím cơ Akko 3087 v2 DS Midnight với thiết kế TKL, keycap PBT Double-shot chất lượng cao và switch Akko CS Jelly Pink mang lại cảm giác gõ êm ái, là lựa chọn tuyệt vời cho cả gaming và văn phòng với mức giá hợp lý.', 'Bàn phím', '6da6eea4-47d4-4ee7-a12b-2aef25aa0336', 'Akko', '{"Switch": "Akko CS Jelly Pink", "K\u1ebft n\u1ed1i": "C\u00f3 d\u00e2y USB Type-C", "\u0110\u00e8n LED": "Kh\u00f4ng", "Ph\u00edm multimedia": "C\u00f3 (Fn)", "K\u00edch th\u01b0\u1edbc": "Tenkeyless (TKL)", "Keycap": "PBT Double-shot", "Polling Rate": "1000Hz"}', '/static/images/keyboard-002.jpg', '["/static/images/keyboard-002.jpg"]', 1290000, 1548000, 1290000, 100, 5.0, true, true);
INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('266f6e01-6db0-435b-ad67-a2f4bae0be82', 'Chuột gaming Logitech G Pro X Superlight', 'Chuột gaming Logitech G Pro X Superlight với trọng lượng siêu nhẹ chỉ 63g, cảm biến HERO 25K chính xác và công nghệ không dây Lightspeed độc quyền, là lựa chọn hàng đầu của các game thủ chuyên nghiệp.', 'Chuột', '283cda82-b2df-4744-ac57-ef4e6940491e', 'Logitech', '{"DPI": "25600", "K\u1ebft n\u1ed1i": "Wireless (Lightspeed)", "C\u1ea3m bi\u1ebfn": "HERO 25K", "Switch": "Omron 20 tri\u1ec7u l\u1ea7n nh\u1ea5n", "Tr\u1ecdng l\u01b0\u1ee3ng": "63g", "Pin": "70 gi\u1edd", "N\u00fat b\u1ea5m": "5 n\u00fat"}', '/static/images/mouse-001.jpg', '["/static/images/mouse-001.jpg"]', 2990000, 3588000, 2990000, 100, 5.0, true, true);
INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('9a089c2a-7e3e-428b-90ad-4a2561607da3', 'Tai nghe Gaming HyperX Cloud Alpha', 'Tai nghe Gaming HyperX Cloud Alpha với công nghệ driver dual chamber độc đáo mang đến chất âm chi tiết, chính xác, microphone có thể tháo rời và khung nhôm bền bỉ, là lựa chọn hàng đầu cho các game thủ đòi hỏi chất lượng âm thanh cao cấp.', 'Tai nghe', '8a99a3a7-2bb0-41c8-baee-20d6ff2d5cb7', 'HyperX', '{"Driver": "50mm Dual Chamber", "K\u1ebft n\u1ed1i": "3.5mm", "Microphone": "C\u00f3 th\u1ec3 th\u00e1o r\u1eddi", "Tr\u1edf kh\u00e1ng": "65 ohm", "T\u1ea7n s\u1ed1": "13Hz - 27.000Hz", "Tr\u1ecdng l\u01b0\u1ee3ng": "336g", "Ki\u1ec3u \u0111eo": "Over-ear"}', '/static/images/headphone-001.jpg', '["/static/images/headphone-001.jpg"]', 1990000, 2388000, 1990000, 100, 5.0, true, true);
INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('4ebe8fb3-1c3f-47e9-9fd9-10ac1cf54d9d', 'SSD Samsung 970 EVO Plus 1TB M.2 NVMe', 'SSD Samsung 970 EVO Plus 1TB M.2 NVMe với tốc độ đọc/ghi ấn tượng, công nghệ V-NAND tiên tiến và độ bền cao, là giải pháp nâng cấp hoàn hảo cho laptop và PC, giúp tăng tốc đáng kể hiệu năng hệ thống.', 'Linh kiện', 'aeae1e29-cc95-4ca0-88cb-342f6062c524', 'Samsung', '{"Dung l\u01b0\u1ee3ng": "1TB", "Chu\u1ea9n giao ti\u1ebfp": "NVMe PCIe Gen 3.0 x4", "T\u1ed1c \u0111\u1ed9 \u0111\u1ecdc": "3500 MB/s", "T\u1ed1c \u0111\u1ed9 ghi": "3300 MB/s", "NAND": "V-NAND 3-bit MLC", "Tu\u1ed5i th\u1ecd": "600 TBW", "B\u1ea3o h\u00e0nh": "5 n\u0103m"}', '/static/images/ssd-001.jpg', '["/static/images/ssd-001.jpg"]', 2790000, 3348000, 2790000, 100, 5.0, true, true);
INSERT INTO products (id, title, description, category, category_id, brand, specs, image, images, price, original_price, sale_price, stock, rating, is_active, is_featured) VALUES ('1ba40a54-5757-4b3b-9cce-29bcfedd1e64', 'Card màn hình ASUS TUF Gaming GeForce RTX 4070 OC 12GB GDDR6X', 'Card màn hình ASUS TUF Gaming GeForce RTX 4070 OC 12GB GDDR6X với kiến trúc NVIDIA Ada Lovelace mới nhất, công nghệ DLSS 3 và Ray Tracing thế hệ thứ 3, mang đến hiệu năng gaming tuyệt vời ở độ phân giải 1440p và 4K.', 'Linh kiện', 'aeae1e29-cc95-4ca0-88cb-342f6062c524', 'Asus', '{"GPU": "NVIDIA GeForce RTX 4070", "VRAM": "12GB GDDR6X", "Xung nh\u1ecbp": "2610 MHz (OC Mode)", "CUDA Cores": "5888", "Giao ti\u1ebfp": "PCIe 4.0", "C\u1ed5ng k\u1ebft n\u1ed1i": "3x DisplayPort 1.4a, 1x HDMI 2.1", "Ngu\u1ed3n \u0111\u1ec1 ngh\u1ecb": "750W", "K\u00edch th\u01b0\u1edbc": "305 x 140 x 65 mm"}', '/static/images/gpu-001.jpg', '["/static/images/gpu-001.jpg"]', 17990000, 21588000, 17990000, 100, 5.0, true, true);
