-- ALTER TABLE to add brand and specs in case they are missing
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='products' AND column_name='brand') THEN
        ALTER TABLE products ADD COLUMN brand VARCHAR(100);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='products' AND column_name='specs') THEN
        ALTER TABLE products ADD COLUMN specs JSONB DEFAULT '{}';
    END IF;
END $$;

